function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let pathname = url.pathname;
    if (pathname.endsWith('/')) pathname += 'index.html';
    const asset = ASSETS[pathname] || ASSETS['/' + pathname.replace(/^\/+/, '')];
    if (!asset) return new Response('Not found', { status: 404 });
    const body = decodeBase64(asset.base64);
    return new Response(body, { headers: { 'Content-Type': asset.mime, 'Cache-Control': asset.mime.startsWith('text/html') ? 'no-store' : 'public, max-age=3600' } });
  }
};
